<?php
function migrate_reservations(PDO $db): void {if($db->query("SELECT version FROM schema_migrations WHERE version='011_reservations'")->fetchColumn())return;$sqlite=$db->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite';$cols=$sqlite?array_column($db->query('PRAGMA table_info(stock)')->fetchAll(),'name'):array_column($db->query('SHOW COLUMNS FROM stock')->fetchAll(),'Field');if(!in_array('reserved_qty',$cols,true))$db->exec('ALTER TABLE stock ADD COLUMN reserved_qty DECIMAL(18,3) NOT NULL DEFAULT 0');$cols=$sqlite?array_column($db->query('PRAGMA table_info(inventory_transfers)')->fetchAll(),'name'):array_column($db->query('SHOW COLUMNS FROM inventory_transfers')->fetchAll(),'Field');if(!in_array('is_reserved',$cols,true))$db->exec('ALTER TABLE inventory_transfers ADD COLUMN is_reserved INT NOT NULL DEFAULT 0');$db->exec("INSERT INTO schema_migrations (version) VALUES ('011_reservations')");}
